/**
 * Shift a stored range for an insertion of `count` slots at index `at`.
 * Returns the original text untouched when it cannot be parsed.
 *
 * @param {string} range
 * @param {Axis} axis
 * @param {number} at
 * @param {number} count
 * @returns {ShiftResult}
 */
export function shiftRangeOnInsert(range, axis, at, count) {
  const rect = parseA1Range(range);
  if (!rect) return { range, changed: false };
  const { rect: next, changed } = applyInsert(rect, axis, at, count);
  return { range: changed ? formatA1Range(next) : range, changed };
}

/**
 * Shift a stored range for a deletion at index `at`.
 *
 * @param {string} range
 * @param {Axis} axis
 * @param {number} at
 * @returns {{ range: string | null, changed: boolean }} `range === null` = remove.
 */
export function shiftRangeOnDelete(range, axis, at) {
  const rect = parseA1Range(range);
  if (!rect) return { range, changed: false };
  const result = applyDelete(rect, axis, at);
  if (result === null) return { range: null, changed: true };
  return { range: result.changed ? formatA1Range(result.rect) : range, changed: result.changed };
}

